/**
 * Native DateInterval properties dumpable by parent::__serialize().
 */
private const DATE_INTERVAL_PROPERTIES = [
    'y' => true,
    'm' => true,
    'd' => true,
    'h' => true,
    'i' => true,
    's' => true,
    'f' => true,
    'invert' => true,
    'days' => true,
    'from_string' => true,
    'date_string' => true,
];

/**
 * Returns the values to dump on serialize() called on.
 *
 * @return array
 */
public function __serialize(): array
{
    $properties = [];

    foreach (get_object_vars($this) as $key => $value) {
        if ($key === 'localTranslator') {
            if ($value !== null) {
                $properties['dumpLocale'] = $this->getTranslatorLocale();
            }

            continue;
        }

        $properties[$key] = $value;
    }

    return $properties;
}

/**
 * Set locale and restore dumpable properties on unserialize() called on.
 *
 * @param array $data data as generated by __serialize()
 */
public function __unserialize(array $data): void
{
    $intervalData = \array_intersect_key($data, self::DATE_INTERVAL_PROPERTIES);

    if (method_exists(parent::class, '__unserialize')) {
        parent::__unserialize($intervalData + ['from_string' => false]);
    } else {
        foreach ($intervalData as $key => $value) {
            if ($key === 'from_string' || $key === 'date_string') {
                continue;
            }

            $this->$key = $value;
        }

