public function __unserialize(array $data): void
{
    $dump = [];

    foreach ($data as $key => $value) {
        // Clean up visibility prefixes used in dumps made by PHP native
        // serialization or by Carbon prior to version 3
        $dump[preg_replace('/^\x00[^\x00]*\x00/', '', $key)] = $value;
    }

    $intervalData = \array_intersect_key($dump, self::DATE_INTERVAL_PROPERTIES);

