/**
 * Translators contain native closures (for lazy rules such as ordinal ones),
 * so we dump only the locale then rebuild a fresh translator on unserialize().
 *
 * @return array
 */
public function __serialize(): array
{
    return [
        'locale' => $this->getLocale(),
    ];
}

/**
 * Rebuild the translator from its locale on unserialize() called on.
 *
 * @param array $data data as generated by __serialize()
 */
public function __unserialize(array $data): void
{
    $this->__construct($data['locale'] ?? 'en');
}

